//! Fixed, untagged original TryCatch parameter-count Warning.
use super::*;
pub(super) struct Catch<'a,'w,W,R:?Sized>{pub(super) inner:Arguments<'a,'w,W,R>}
impl<W:EffectReportWork,R:Resolver+?Sized> crate::checker_expression_visit::CatchObserver<PolicyFailure> for Catch<'_,'_,W,R>{fn parameters(&mut self,count:usize,at:Span,expression:Span)->Result<(),PolicyFailure>{if count<=1{return Ok(())}let message=text(self.inner.work,format_args!("Expected 0 or 1 catch parameters, got {count}"))?;push(self.inner.work,&mut self.inner.rows,Row{registration:Some((None,crate::check_policy::DiagnosticSeverity::Warning)),diagnostic:Diagnostic{family:"catch_parameter_count",severity:Severity::Warning,span:at,expression_span:expression,message,notes:Vec::new()},synthetic:false,reported:None})}}
pub fn with_archived_body<W:EffectReportWork,R:Resolver+?Sized>(archive:&BodyArchive,body:&ArchivedBody<'_>,resolver:&R,profile:PackedU128,work:&mut W,checkpoint:&dyn Fn()->io::Result<()>,consume:impl FnOnce(&Findings<'_>)->Result<(),PolicyFailure>)->Result<(),PolicyFailure>{checkpoint().map_err(PolicyFailure::Operational)?;if !body.belongs_to(archive)||resolver.source_owner()!=Some(std::ptr::from_ref(archive.tree()).cast()){return Err("catch policy belongs to another actual archive/body/resolver".into())}archive.tree().validate_checker_builtin_profile(profile).map_err(|error|format!("catch actual profile: {error:?}"))?;let mut observer=Catch{inner:Arguments{archive,profile,work,checkpoint,resolver,rows:Vec::new()}};let pending=(||{crate::checker_expression_visit::catch_parameters_archived(archive,body,resolver,profile,checkpoint,&mut observer)?;let findings=Findings::from_rows(observer.inner.archive,std::mem::take(&mut observer.inner.rows));checkpoint().map_err(PolicyFailure::Operational)?;consume(&findings)})();if matches!(&pending,Err(PolicyFailure::Operational(_))){return pending}checkpoint().map_err(PolicyFailure::Operational)?;pending}
